String _svg(String body) => '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">$body</svg>';

class SolarIcon extends StatelessWidget {
  const SolarIcon(this.body, {super.key, this.color, this.size = 24});

  /// A category icon by stored name; unknown names fall back to "tag".
  SolarIcon.category(String name, {Key? key, Color? color, double size = 24})
    : this(categoryIcons[name] ?? categoryIcons['tag']!, key: key, color: color, size: size);

  SolarIcon.ui(Ui icon, {Key? key, Color? color, double size = 24})
    : this(icon.body, key: key, color: color, size: size);

  final String body;
  final Color? color;
  final double size;

  @override
  Widget build(BuildContext context) {
    final icon = IconTheme.of(context);
    return SvgPicture.string(
      _svg(body),
      width: size,
      height: size,
      // srcIn keeps each layer's alpha, so the duotone layers stay visible.
      colorFilter: ColorFilter.mode(color ?? icon.color!, BlendMode.srcIn),
    );
  }
}
